// Figma Sandbox Thread (code.ts)
// Compiles to /code.js in the root
figma.showUI(__html__, { width: 420, height: 600, themeColors: true });
// Helper to convert HEX to Figma RGB [0, 1]
function hexToRgb(hex) {
    const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
    return result ? {
        r: parseInt(result[1], 16) / 255,
        g: parseInt(result[2], 16) / 255,
        b: parseInt(result[3], 16) / 255
    } : { r: 1, g: 1, b: 1 };
}
// Decodes base64 string into Uint8Array (required for figma.createImage)
function base64ToUint8Array(base64) {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const lookup = new Uint8Array(256);
    for (let i = 0; i < chars.length; i++) {
        lookup[chars.charCodeAt(i)] = i;
    }
    const len = base64.length;
    let bufferLength = len * 0.75;
    if (base64[len - 1] === "=") {
        bufferLength--;
        if (base64[len - 2] === "=") {
            bufferLength--;
        }
    }
    const bytes = new Uint8Array(bufferLength);
    let p = 0;
    for (let i = 0; i < len; i += 4) {
        const encode1 = lookup[base64.charCodeAt(i)];
        const encode2 = lookup[base64.charCodeAt(i + 1)];
        const encode3 = lookup[base64.charCodeAt(i + 2)];
        const encode4 = lookup[base64.charCodeAt(i + 3)];
        bytes[p++] = (encode1 << 2) | (encode2 >> 4);
        if (p < bufferLength) {
            bytes[p++] = ((encode2 & 15) << 4) | (encode3 >> 2);
        }
        if (p < bufferLength) {
            bytes[p++] = ((encode3 & 3) << 6) | (encode4 & 63);
        }
    }
    return bytes;
}
// Helper to get custom transparent team logo base64 data from local memory using the extracted mapping
function getCustomLogoBase64(shortName, isHome) {
    if (!shortName)
        return null;
    const name = shortName.toUpperCase().trim();
    // Normalize incoming team codes
    let code = name;
    if (name === "DPT")
        code = "DEP";
    const localLogos = {
        "ANI": logo_local_ANI,
        "APK": logo_local_APK,
        "DEP": logo_local_DEP,
        "DR7": logo_local_DR7,
        "FUR": logo_local_FUR,
        "FWZ": logo_local_FWZ,
        "G3X": logo_local_G3X,
        "KRS": logo_local_KRS,
        "LCA": logo_local_LCA,
        "NRF": logo_local_NRF,
        "POR": logo_local_POR,
        "PRC": logo_local_PRC,
        "STL": logo_local_STL,
        "TFC": logo_local_TFC,
        "ULT": logo_local_ULT,
        "UND": logo_local_UND
    };
    const awayLogos = {
        "ANI": logo_away_ANI,
        "APK": logo_away_APK,
        "DEP": logo_away_DEP,
        "DR7": logo_away_DR7,
        "FUR": logo_away_FUR,
        "FWZ": logo_away_FWZ,
        "G3X": logo_away_G3X,
        "KRS": logo_away_KRS,
        "LCA": logo_away_LCA,
        "NRF": logo_away_NRF,
        "POR": logo_away_POR,
        "PRC": logo_away_PRC,
        "STL": logo_away_STL,
        "TFC": logo_away_TFC,
        "ULT": logo_away_ULT,
        "UND": logo_away_UND
    };
    const map = isHome ? localLogos : awayLogos;
    return map[code] || null;
}
// Helper to load standard fonts dynamically
async function loadFont(isBold = false, family = 'Inter', explicitStyle = null) {
    if (family === 'Sharp Grotesk') {
        try {
            const styleName = explicitStyle !== null ? explicitStyle : (isBold ? "Bold 10" : "Medium 10");
            const font = { family: "Sharp Grotesk", style: styleName };
            await figma.loadFontAsync(font);
            return font;
        }
        catch (e) {
            // Fallback to Inter
        }
    }
    if (family === 'Termina') {
        try {
            const font = { family: "Termina", style: isBold ? "Bold" : "Regular" };
            await figma.loadFontAsync(font);
            return font;
        }
        catch (e) {
            // Fallback to Inter
        }
    }
    const font = { family: "Inter", style: isBold ? "Bold" : "Regular" };
    await figma.loadFontAsync(font);
    return font;
}
// Helper to create and style text nodes
async function createTextNode(parent, characters, fontSize, isBold, colorHex, align = "LEFT", family = 'Inter', fontStyle = null) {
    const text = figma.createText();
    const font = await loadFont(isBold, family, fontStyle);
    text.fontName = font;
    text.fontSize = fontSize;
    text.characters = characters;
    text.fills = [{ type: 'SOLID', color: hexToRgb(colorHex) }];
    text.textAlignHorizontal = align;
    parent.appendChild(text);
    return text;
}
// Helper function to build a complete Match Card Frame node (Standard Style)
async function createMatchCardNode(match, competitionName, turnName, updatedLabel, weekday, time, date, penaltiesText, isResult = true) {
    // 1. Create main container frame
    const cardFrame = figma.createFrame();
    cardFrame.name = `MatchCard - ${match.homeTeam.shortName || match.homeTeam.name} vs ${match.awayTeam.shortName || match.awayTeam.name}`;
    cardFrame.resize(360, 260);
    cardFrame.cornerRadius = 20;
    // Auto Layout settings
    cardFrame.layoutMode = "VERTICAL";
    cardFrame.primaryAxisSizingMode = "AUTO"; // height hugs content
    cardFrame.counterAxisSizingMode = "FIXED"; // fixed width
    cardFrame.paddingLeft = 24;
    cardFrame.paddingRight = 24;
    cardFrame.paddingTop = 20;
    cardFrame.paddingBottom = 20;
    cardFrame.itemSpacing = 16;
    // Dark card styling
    cardFrame.fills = [{
            type: 'SOLID',
            color: hexToRgb('#16161A')
        }];
    cardFrame.strokes = [{
            type: 'SOLID',
            color: hexToRgb('#2D2D35')
        }];
    cardFrame.strokeWeight = 1;
    // Add a shadow effect
    cardFrame.effects = [{
            type: 'DROP_SHADOW',
            color: { r: 0, g: 0, b: 0, a: 0.4 },
            offset: { x: 0, y: 12 },
            radius: 24,
            visible: true,
            blendMode: 'NORMAL'
        }];
    // 2. Header Row (Competition Brand & Turn Name)
    const headerFrame = figma.createFrame();
    headerFrame.name = "Header";
    headerFrame.layoutMode = "HORIZONTAL";
    headerFrame.primaryAxisSizingMode = "AUTO";
    headerFrame.counterAxisSizingMode = "AUTO";
    headerFrame.layoutAlign = "STRETCH";
    headerFrame.itemSpacing = 8;
    headerFrame.fills = []; // transparent
    headerFrame.backgrounds = [];
    // Logo Badge
    const badgeFrame = figma.createFrame();
    badgeFrame.name = "Badge";
    badgeFrame.layoutMode = "HORIZONTAL";
    badgeFrame.primaryAxisSizingMode = "AUTO";
    badgeFrame.counterAxisSizingMode = "AUTO";
    badgeFrame.paddingLeft = 8;
    badgeFrame.paddingRight = 8;
    badgeFrame.paddingTop = 4;
    badgeFrame.paddingBottom = 4;
    badgeFrame.cornerRadius = 6;
    // Dynamic competition colors
    let compColor = '#F2B800'; // Default Kings Yellow
    const compUpper = (competitionName || '').toUpperCase();
    if (compUpper.includes('QUEENS')) {
        compColor = '#E5007E'; // Queens Pink
    }
    else if (compUpper.includes('WORLD CUP') || compUpper.includes('KWCC')) {
        compColor = '#D4AF37'; // KWCC Gold
    }
    else if (compUpper.includes('KWCN')) {
        compColor = '#00FF66'; // KWCN Neon Green
    }
    badgeFrame.fills = [{ type: 'SOLID', color: hexToRgb(compColor) }];
    const badgeText = figma.createText();
    const boldFont = await loadFont(true, 'Sharp Grotesk');
    badgeText.fontName = boldFont;
    badgeText.fontSize = 9;
    badgeText.characters = (competitionName || "KINGS LEAGUE").toUpperCase();
    badgeText.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    badgeFrame.appendChild(badgeText);
    headerFrame.appendChild(badgeFrame);
    // Turn Info Text
    await createTextNode(headerFrame, turnName.toUpperCase(), 11, true, '#FFFFFF');
    // Spacer to push elements to both sides
    const spacer = figma.createFrame();
    spacer.name = "Spacer";
    spacer.fills = [];
    headerFrame.appendChild(spacer);
    // Update/Import timestamp
    await createTextNode(headerFrame, updatedLabel, 9, false, '#8E8E9C', 'RIGHT');
    cardFrame.appendChild(headerFrame);
    // 3. Separator Line
    const sep = figma.createFrame();
    sep.name = "Separator";
    sep.layoutAlign = "STRETCH";
    sep.resize(sep.width, 1);
    sep.fills = [{ type: 'SOLID', color: hexToRgb('#2D2D35') }];
    cardFrame.appendChild(sep);
    // 4. Scoreboard Row (Home vs Away)
    const scoreFrame = figma.createFrame();
    scoreFrame.name = "Scoreboard";
    scoreFrame.layoutMode = "HORIZONTAL";
    scoreFrame.primaryAxisSizingMode = "AUTO";
    scoreFrame.counterAxisSizingMode = "AUTO";
    scoreFrame.layoutAlign = "STRETCH";
    scoreFrame.itemSpacing = 12;
    scoreFrame.fills = [];
    // A. Home Team Block
    const homeBlock = figma.createFrame();
    homeBlock.name = "HomeTeam";
    homeBlock.layoutMode = "VERTICAL";
    homeBlock.primaryAxisSizingMode = "AUTO";
    homeBlock.counterAxisSizingMode = "FIXED";
    homeBlock.resize(100, homeBlock.height);
    homeBlock.itemSpacing = 8;
    homeBlock.fills = [];
    // Home Logo Node
    const homeLogoNode = figma.createEllipse();
    homeLogoNode.name = "Logo";
    homeLogoNode.resize(48, 48);
    homeLogoNode.fills = [{ type: 'SOLID', color: hexToRgb(match.homeTeam.colorHex) }];
    if (match.homeTeam.logoUrl) {
        try {
            const img = await figma.createImageAsync(match.homeTeam.logoUrl);
            homeLogoNode.fills = [{
                    type: 'IMAGE',
                    imageHash: img.hash,
                    scaleMode: 'FILL'
                }];
        }
        catch (e) {
            console.log("Could not load home logo image directly, falling back to brand color background");
        }
    }
    homeBlock.appendChild(homeLogoNode);
    // Home Name
    const homeName = await createTextNode(homeBlock, match.homeTeam.shortName || match.homeTeam.name, 12, true, '#FFFFFF', 'CENTER');
    homeName.layoutAlign = "STRETCH";
    scoreFrame.appendChild(homeBlock);
    // B. VS / Score Info Block
    const vsBlock = figma.createFrame();
    vsBlock.name = "VS_Block";
    vsBlock.layoutMode = "VERTICAL";
    vsBlock.primaryAxisSizingMode = "AUTO";
    vsBlock.counterAxisSizingMode = "FIXED";
    vsBlock.resize(100, vsBlock.height);
    vsBlock.itemSpacing = 4;
    vsBlock.fills = [];
    const hasScore = isResult && match.scores.homeScore !== null && match.scores.awayScore !== null;
    if (hasScore) {
        // Render score numbers
        const scoreRow = figma.createFrame();
        scoreRow.name = "Score";
        scoreRow.layoutMode = "HORIZONTAL";
        scoreRow.primaryAxisSizingMode = "AUTO";
        scoreRow.counterAxisSizingMode = "AUTO";
        scoreRow.itemSpacing = 8;
        scoreRow.fills = [];
        await createTextNode(scoreRow, String(match.scores.homeScore), 24, true, '#FFFFFF', 'RIGHT');
        await createTextNode(scoreRow, "-", 18, true, '#4E4E5A', 'CENTER');
        await createTextNode(scoreRow, String(match.scores.awayScore), 24, true, '#FFFFFF', 'LEFT');
        vsBlock.appendChild(scoreRow);
        // Penalties if present
        if (penaltiesText) {
            await createTextNode(vsBlock, penaltiesText, 9, true, '#FBB800', 'CENTER');
        }
    }
    else {
        // Render simple VS
        const vsBadge = figma.createFrame();
        vsBadge.name = "VS";
        vsBadge.layoutMode = "HORIZONTAL";
        vsBadge.primaryAxisSizingMode = "AUTO";
        vsBadge.counterAxisSizingMode = "AUTO";
        vsBadge.paddingLeft = 10;
        vsBadge.paddingRight = 10;
        vsBadge.paddingTop = 4;
        vsBadge.paddingBottom = 4;
        vsBadge.cornerRadius = 20;
        vsBadge.fills = [{ type: 'SOLID', color: hexToRgb('#2D2D35') }];
        const vsTextNode = figma.createText();
        vsTextNode.fontName = boldFont;
        vsTextNode.fontSize = 11;
        vsTextNode.characters = "VS";
        vsTextNode.fills = [{ type: 'SOLID', color: hexToRgb('#8E8E9C') }];
        vsBadge.appendChild(vsTextNode);
        vsBlock.appendChild(vsBadge);
    }
    // Add date/time indicator
    const weekdayStr = weekday || "TBD";
    const timeStr = time || "TBD";
    const dateStr = date || "";
    const dateLine = dateStr ? `${weekdayStr} · ${dateStr}` : weekdayStr;
    await createTextNode(vsBlock, dateLine, 9, false, '#8E8E9C', 'CENTER');
    await createTextNode(vsBlock, timeStr, 9, false, '#8E8E9C', 'CENTER');
    scoreFrame.appendChild(vsBlock);
    // C. Away Team Block
    const awayBlock = figma.createFrame();
    awayBlock.name = "AwayTeam";
    awayBlock.layoutMode = "VERTICAL";
    awayBlock.primaryAxisSizingMode = "AUTO";
    awayBlock.counterAxisSizingMode = "FIXED";
    awayBlock.resize(100, awayBlock.height);
    awayBlock.itemSpacing = 8;
    awayBlock.fills = [];
    // Away Logo Node
    const awayLogoNode = figma.createEllipse();
    awayLogoNode.name = "Logo";
    awayLogoNode.resize(48, 48);
    awayLogoNode.fills = [{ type: 'SOLID', color: hexToRgb(match.awayTeam.colorHex) }];
    if (match.awayTeam.logoUrl) {
        try {
            const img = await figma.createImageAsync(match.awayTeam.logoUrl);
            awayLogoNode.fills = [{
                    type: 'IMAGE',
                    imageHash: img.hash,
                    scaleMode: 'FILL'
                }];
        }
        catch (e) {
            console.log("Could not load away logo image directly, falling back to brand color background");
        }
    }
    awayBlock.appendChild(awayLogoNode);
    // Away Name
    const awayName = await createTextNode(awayBlock, match.awayTeam.shortName || match.awayTeam.name, 12, true, '#FFFFFF', 'CENTER');
    awayName.layoutAlign = "STRETCH";
    scoreFrame.appendChild(awayBlock);
    cardFrame.appendChild(scoreFrame);
    return cardFrame;
}
// Helper to build KWCC Poster Frame nodes
async function createKWCCArtboard(matches, competitionName, turnName, updatedLabel, isResult, width, height, formatName) {
    const artboard = figma.createFrame();
    artboard.name = `${formatName} - ${competitionName} - ${turnName}`;
    artboard.resize(width, height);
    // Load the designer background image dynamically from base64
    let bgBase64 = storiesBgBase64;
    if (formatName === "Portraits") {
        bgBase64 = portraitsBgBase64;
    }
    else if (formatName === "Thumbs") {
        bgBase64 = thumbsBgBase64;
    }
    try {
        const uint8 = base64ToUint8Array(bgBase64);
        const figmaImage = figma.createImage(uint8);
        artboard.fills = [{
                type: 'IMAGE',
                imageHash: figmaImage.hash,
                scaleMode: 'FILL'
            }];
    }
    catch (e) {
        // Fallback to solid color if loading fails
        artboard.fills = [{
                type: 'SOLID',
                color: hexToRgb('#0C0C0E')
            }];
    }
    // If format is Thumbs (Landscape 1920x1080)
    if (formatName === "Thumbs") {
        // 1. Header
        const titleText = await createTextNode(artboard, competitionName.toUpperCase(), 32, true, '#D4AF37', 'CENTER', 'Sharp Grotesk');
        titleText.x = (width - titleText.width) / 2;
        titleText.y = 80;
        const roundText = await createTextNode(artboard, turnName.toUpperCase(), 73.11, true, '#D4B78E', 'CENTER', 'Termina');
        roundText.x = (width - roundText.width) / 2;
        roundText.y = 135;
        roundText.letterSpacing = { value: 0.73, unit: 'PIXELS' };
        const dateText = await createTextNode(artboard, updatedLabel.toUpperCase(), 32.71, false, '#FFFFFF', 'CENTER', 'Sharp Grotesk', 'Medium 20');
        dateText.x = (width - dateText.width) / 2;
        dateText.y = 205;
        dateText.letterSpacing = { value: 3.27, unit: 'PIXELS' };
        // 2. Two-column match grid — shows ALL matches, no row limit
        // Layout: 2 equal columns of 870px with a 180px gap between them
        // Col1 x=40, Col2 x=1090  →  40+870+180+870+(-60)? Let's use: Col1=40, Col2=1010, 40+870+100+870+40=1920 ✓
        const COL_W = 870; // column width
        const COL_LEFT = 40; // left column x-start
        const COL_RIGHT = 1010; // right column x-start  (40 + 870 + 100 = 1010; 1010+870+40=1920 ✓)
        const T_ROW_H = 190; // match row height for Thumbs
        const T_ROW_GAP = 15; // vertical gap between rows within a column
        const T_START_Y = 289; // y-start of first row (below header)
        // Per-row element sizes (within a 870px-wide column)
        const T_LOGO_W = 285; // logo width
        const T_AWAY_X = COL_W - T_LOGO_W; // = 585 (away logo x-offset inside row)
        const T_BADGE_W = 260; // time badge width
        const T_BADGE_H = 109; // time badge height
        const T_BADGE_X = Math.round((COL_W - T_BADGE_W) / 2); // = 305
        const T_BADGE_Y = Math.round((T_ROW_H - T_BADGE_H) / 2); // = 35
        // Split matches into left and right columns
        const half = Math.ceil(matches.length / 2);
        for (let ci = 0; ci < 2; ci++) {
            const colX = ci === 0 ? COL_LEFT : COL_RIGHT;
            const colStart = ci === 0 ? 0 : half;
            const colEnd = ci === 0 ? half : matches.length;
            for (let ri = 0; ri < colEnd - colStart; ri++) {
                const m = matches[colStart + ri];
                if (!m)
                    break;
                const matchRow = figma.createFrame();
                matchRow.name = `Match - ${m.match.homeTeam.shortName || m.match.homeTeam.name} vs ${m.match.awayTeam.shortName || m.match.awayTeam.name}`;
                matchRow.resize(COL_W, T_ROW_H);
                matchRow.x = colX;
                matchRow.y = T_START_Y + ri * (T_ROW_H + T_ROW_GAP);
                matchRow.fills = [];
                matchRow.backgrounds = [];
                matchRow.clipsContent = false;
                artboard.appendChild(matchRow);
                // Time Badge — appended FIRST = bottom layer (logos appear on top)
                const timeBadge = figma.createFrame();
                timeBadge.name = "Time Badge";
                timeBadge.resize(T_BADGE_W, T_BADGE_H);
                timeBadge.x = T_BADGE_X;
                timeBadge.y = T_BADGE_Y;
                timeBadge.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
                matchRow.appendChild(timeBadge);
                // Time / Score text — HeadingNow-36Bold 63.79px, letterSpacing 1.28px
                const timeDisplayStr = isResult && m.match.scores.homeScore !== null && m.match.scores.awayScore !== null
                    ? `${m.match.scores.homeScore} - ${m.match.scores.awayScore}`
                    : (m.time ? (m.time.includes('h') ? m.time : `${m.time}h`) : "19:00h");
                const tTimeText = figma.createText();
                try {
                    await figma.loadFontAsync({ family: "HeadingNow-36Bold", style: "Regular" });
                    tTimeText.fontName = { family: "HeadingNow-36Bold", style: "Regular" };
                }
                catch (e) {
                    await figma.loadFontAsync({ family: "Inter", style: "Bold" });
                    tTimeText.fontName = { family: "Inter", style: "Bold" };
                }
                tTimeText.fontSize = 63.79;
                tTimeText.characters = timeDisplayStr;
                tTimeText.letterSpacing = { unit: 'PIXELS', value: 1.28 };
                tTimeText.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
                tTimeText.textAlignHorizontal = "CENTER";
                tTimeText.textAlignVertical = "CENTER";
                timeBadge.appendChild(tTimeText);
                tTimeText.resize(T_BADGE_W, T_BADGE_H);
                tTimeText.x = 0;
                tTimeText.y = 0;
                // Home Logo — appended AFTER badge = above badge in layer stack (on top)
                const homeLogoNode = figma.createRectangle();
                homeLogoNode.name = "Home Logo";
                homeLogoNode.resize(T_LOGO_W, T_ROW_H);
                homeLogoNode.x = 50;
                homeLogoNode.y = 0;
                homeLogoNode.fills = [];
                const homeBase64 = getCustomLogoBase64(m.match.homeTeam.shortName, true);
                if (homeBase64) {
                    try {
                        const uint8 = base64ToUint8Array(homeBase64);
                        const img = figma.createImage(uint8);
                        homeLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                    }
                    catch (e) { }
                }
                else if (m.match.homeTeam.logoUrl) {
                    try {
                        const img = await figma.createImageAsync(m.match.homeTeam.logoUrl);
                        homeLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                    }
                    catch (e) { }
                }
                matchRow.appendChild(homeLogoNode);
                // Away Logo — appended LAST = top layer
                const awayLogoNode = figma.createRectangle();
                awayLogoNode.name = "Away Logo";
                awayLogoNode.resize(T_LOGO_W, T_ROW_H);
                awayLogoNode.x = T_AWAY_X - 50;
                awayLogoNode.y = 0;
                awayLogoNode.fills = [];
                const awayBase64 = getCustomLogoBase64(m.match.awayTeam.shortName, false);
                if (awayBase64) {
                    try {
                        const uint8 = base64ToUint8Array(awayBase64);
                        const img = figma.createImage(uint8);
                        awayLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                    }
                    catch (e) { }
                }
                else if (m.match.awayTeam.logoUrl) {
                    try {
                        const img = await figma.createImageAsync(m.match.awayTeam.logoUrl);
                        awayLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                    }
                    catch (e) { }
                }
                matchRow.appendChild(awayLogoNode);
            }
        }
    }
    else {
        // Stories or Portraits layout
        // 1. Header (Custom Competition Shield Logo & Titles)
        const isStories = formatName === "Stories";
        const logoW = isStories ? 149.97 : 126.23;
        const logoH = isStories ? 195 : 164.12;
        const compLogoNode = figma.createRectangle();
        compLogoNode.name = "Competition Logo";
        compLogoNode.resize(logoW, logoH);
        compLogoNode.x = (width - logoW) / 2;
        compLogoNode.y = height * 0.06 - (isStories ? 50 : 30);
        try {
            const uint8 = base64ToUint8Array(competitionLogoBase64);
            const img = figma.createImage(uint8);
            compLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
        }
        catch (e) {
            compLogoNode.fills = [{ type: 'SOLID', color: hexToRgb('#D4AF37') }];
        }
        artboard.appendChild(compLogoNode);
        const roundText = await createTextNode(artboard, turnName.toUpperCase(), 73.11, true, '#D4B78E', 'CENTER', 'Termina');
        roundText.x = (width - roundText.width) / 2;
        roundText.y = compLogoNode.y + logoH + 20;
        roundText.letterSpacing = { value: 0.73, unit: 'PIXELS' };
        const dateText = await createTextNode(artboard, updatedLabel.toUpperCase(), 32.71, false, '#FFFFFF', 'CENTER', 'Sharp Grotesk', 'Medium 20');
        dateText.x = (width - dateText.width) / 2;
        dateText.y = roundText.y + roundText.height + 15;
        dateText.letterSpacing = { value: 3.27, unit: 'PIXELS' };
        // 3. Match stack in the center
        // Figma design: row width = 746.69px, logos = 303x149px, time badge = 252x116px at x=251, y=32
        const ROW_W = 747; // match row width (matches Figma: 746.69px)
        const ROW_H = 149; // match row height (matches Figma logo height: 148.806px)
        const LOGO_W = 303; // home logo width  (Figma: 302.927px)
        const LOGO_H = 149; // logo height      (Figma: 148.806px)
        const AWAY_LOGO_W = 302; // away logo width (Figma: 302.042px)
        const TIME_W = 252; // time badge width  (Figma: 252.44px)
        const TIME_H = 115; // time badge height
        const TIME_X = 252; // time badge x      (Figma: 251.55px)
        const TIME_Y = 30; // time badge y (moved 3px up)
        const AWAY_X = 445; // away logo x       (Figma: 444.65px)
        const startY = 440;
        const matchSpacing = 20; // vertical gap between rows
        let index = 0;
        for (const m of matches) {
            const matchRow = figma.createFrame();
            matchRow.name = `Match - ${m.match.homeTeam.shortName || m.match.homeTeam.name} vs ${m.match.awayTeam.shortName || m.match.awayTeam.name}`;
            matchRow.resize(ROW_W, ROW_H);
            matchRow.x = (width - ROW_W) / 2;
            matchRow.y = startY + (index * (ROW_H + matchSpacing));
            matchRow.fills = [];
            matchRow.backgrounds = [];
            matchRow.clipsContent = false; // no mask — allow full logo visibility
            artboard.appendChild(matchRow);
            // Time Badge — appended FIRST = bottom layer (logos rendered on top)
            // Figma: w=252.44px h=116.034px at x=251.55px y=32.77px
            const timeBadge = figma.createFrame();
            timeBadge.name = "Time Badge";
            timeBadge.resize(TIME_W, TIME_H);
            timeBadge.x = TIME_X;
            timeBadge.y = TIME_Y;
            timeBadge.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
            matchRow.appendChild(timeBadge);
            // Time Text — HeadingNow-36Bold 63.79px, letterSpacing 1.28px, white
            const displayTime = isResult && m.match.scores.homeScore !== null && m.match.scores.awayScore !== null
                ? `${m.match.scores.homeScore} - ${m.match.scores.awayScore}`
                : (m.time ? (m.time.includes('h') ? m.time : `${m.time}h`) : "19:00h");
            const sTimeText = figma.createText();
            try {
                await figma.loadFontAsync({ family: "HeadingNow-36Bold", style: "Regular" });
                sTimeText.fontName = { family: "HeadingNow-36Bold", style: "Regular" };
            }
            catch (e) {
                await figma.loadFontAsync({ family: "Inter", style: "Bold" });
                sTimeText.fontName = { family: "Inter", style: "Bold" };
            }
            sTimeText.fontSize = 63.79;
            sTimeText.characters = displayTime;
            sTimeText.letterSpacing = { unit: 'PIXELS', value: 1.28 };
            sTimeText.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
            sTimeText.textAlignHorizontal = "CENTER";
            sTimeText.textAlignVertical = "CENTER";
            timeBadge.appendChild(sTimeText);
            sTimeText.resize(TIME_W, TIME_H);
            sTimeText.x = 0;
            sTimeText.y = 0;
            // Home Team Logo — FIT scale preserves full image without cropping (no mask)
            // Figma: Home Logo w=302.927px h=148.806px at x=0, y=0 (col-1 row-1, no offset)
            const homeLogoNode = figma.createRectangle();
            homeLogoNode.name = "Home Logo";
            homeLogoNode.resize(LOGO_W, LOGO_H);
            homeLogoNode.x = 0;
            homeLogoNode.y = 0;
            homeLogoNode.fills = [];
            const homeBase64 = getCustomLogoBase64(m.match.homeTeam.shortName, true);
            if (homeBase64) {
                try {
                    const uint8 = base64ToUint8Array(homeBase64);
                    const img = figma.createImage(uint8);
                    // FIT = shows entire image within bounds, no cropping (respects full crest integrity)
                    homeLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                }
                catch (e) { }
            }
            else if (m.match.homeTeam.logoUrl) {
                try {
                    const img = await figma.createImageAsync(m.match.homeTeam.logoUrl);
                    homeLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                }
                catch (e) { }
            }
            matchRow.appendChild(homeLogoNode);
            // Away Team Logo — FIT scale preserves full image without cropping (no mask)
            // Figma: Away Logo w=302.042px h=148.806px at x=444.65px, y=0
            const awayLogoNode = figma.createRectangle();
            awayLogoNode.name = "Away Logo";
            awayLogoNode.resize(AWAY_LOGO_W, LOGO_H);
            awayLogoNode.x = AWAY_X;
            awayLogoNode.y = 0;
            awayLogoNode.fills = [];
            const awayBase64 = getCustomLogoBase64(m.match.awayTeam.shortName, false);
            if (awayBase64) {
                try {
                    const uint8 = base64ToUint8Array(awayBase64);
                    const img = figma.createImage(uint8);
                    // FIT = shows entire image within bounds, no cropping (respects full crest integrity)
                    awayLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                }
                catch (e) { }
            }
            else if (m.match.awayTeam.logoUrl) {
                try {
                    const img = await figma.createImageAsync(m.match.awayTeam.logoUrl);
                    awayLogoNode.fills = [{ type: 'IMAGE', imageHash: img.hash, scaleMode: 'FIT' }];
                }
                catch (e) { }
            }
            matchRow.appendChild(awayLogoNode);
            index++;
            const maxRows = height === 1920 ? 8 : 6;
            if (index >= maxRows)
                break;
        }
    }
    return artboard;
}
// Receive messages from Figma UI thread
figma.ui.onmessage = async (msg) => {
    try {
        if (msg.type === 'get-credentials') {
            let username = await figma.clientStorage.getAsync('kama_username');
            let password = await figma.clientStorage.getAsync('kama_password');
            const language = await figma.clientStorage.getAsync('kama_language') || 'es';
            const importStyle = await figma.clientStorage.getAsync('kama_import_style') || 'standard';
            const selectedFormats = await figma.clientStorage.getAsync('kama_selected_formats') || { stories: true, portraits: true, thumbs: true };
            const loggedOut = await figma.clientStorage.getAsync('kama_logged_out');
            // If credentials have never been set, or if they are empty and user hasn't explicitly logged out
            if (username === undefined || password === undefined || (!username && !password && !loggedOut)) {
                username = 'kosmos.design';
                password = 'zbi3WFxW!F2BW#oi';
                await figma.clientStorage.setAsync('kama_username', username);
                await figma.clientStorage.setAsync('kama_password', password);
            }
            figma.ui.postMessage({
                type: 'credentials',
                username: username || '',
                password: password || '',
                language,
                importStyle,
                selectedFormats
            });
        }
        else if (msg.type === 'set-credentials') {
            await figma.clientStorage.setAsync('kama_username', msg.username);
            await figma.clientStorage.setAsync('kama_password', msg.password);
            await figma.clientStorage.deleteAsync('kama_logged_out');
            figma.ui.postMessage({ type: 'credentials-saved' });
        }
        else if (msg.type === 'clear-credentials') {
            await figma.clientStorage.deleteAsync('kama_username');
            await figma.clientStorage.deleteAsync('kama_password');
            await figma.clientStorage.setAsync('kama_logged_out', true);
            figma.ui.postMessage({ type: 'credentials-cleared' });
        }
        else if (msg.type === 'set-language') {
            await figma.clientStorage.setAsync('kama_language', msg.language);
        }
        else if (msg.type === 'set-preferences') {
            await figma.clientStorage.setAsync('kama_import_style', msg.importStyle);
            await figma.clientStorage.setAsync('kama_selected_formats', msg.selectedFormats);
        }
        else if (msg.type === 'import-match-card') {
            const { match, competitionName, turnName, updatedLabel, weekday, time, date, penaltiesText, isResult, notificationText } = msg;
            const cardFrame = await createMatchCardNode(match, competitionName, turnName, updatedLabel, weekday, time, date, penaltiesText, isResult !== false);
            figma.currentPage.appendChild(cardFrame);
            figma.currentPage.selection = [cardFrame];
            figma.viewport.scrollAndZoomIntoView([cardFrame]);
            figma.notify(notificationText || `¡Partido importado al lienzo!`);
        }
        else if (msg.type === 'import-schedule') {
            const { matches, competitionName, turnName, updatedLabel, isResult, notificationText } = msg;
            // Create a vertical stack for the entire schedule
            const containerFrame = figma.createFrame();
            containerFrame.name = `Schedule - ${competitionName} - ${turnName}`;
            containerFrame.layoutMode = "VERTICAL";
            containerFrame.primaryAxisSizingMode = "AUTO"; // hugs content height
            containerFrame.counterAxisSizingMode = "AUTO"; // hugs content width
            containerFrame.itemSpacing = 20; // spacing between cards
            containerFrame.fills = []; // transparent
            containerFrame.backgrounds = [];
            for (const m of matches) {
                const cardFrame = await createMatchCardNode(m.match, competitionName, turnName, updatedLabel, m.weekday, m.time, m.date, m.penaltiesText, isResult !== false);
                containerFrame.appendChild(cardFrame);
            }
            figma.currentPage.appendChild(containerFrame);
            figma.currentPage.selection = [containerFrame];
            figma.viewport.scrollAndZoomIntoView([containerFrame]);
            figma.notify(notificationText || `¡Jornada importada al lienzo!`);
        }
        else if (msg.type === 'import-kwcc-poster') {
            const { matches, competitionName, turnName, updatedLabel, isResult, formats, notificationText } = msg;
            const createdFrames = [];
            // 1. Stories format (1080 x 1920)
            if (formats.stories) {
                const storiesFrame = await createKWCCArtboard(matches, competitionName, turnName, updatedLabel, isResult !== false, 1080, 1920, "Stories");
                createdFrames.push(storiesFrame);
            }
            // 2. Portraits format (1350 x 1920)
            if (formats.portraits) {
                const portraitsFrame = await createKWCCArtboard(matches, competitionName, turnName, updatedLabel, isResult !== false, 1350, 1920, "Portraits");
                createdFrames.push(portraitsFrame);
            }
            // 3. Thumbs format (1920 x 1080)
            if (formats.thumbs) {
                const thumbsFrame = await createKWCCArtboard(matches, competitionName, turnName, updatedLabel, isResult !== false, 1920, 1080, "Thumbs");
                createdFrames.push(thumbsFrame);
            }
            // Layout artboards side-by-side
            let currentX = figma.viewport.center.x - (createdFrames.length * 700) / 2;
            const currentY = figma.viewport.center.y - 800;
            for (const frame of createdFrames) {
                figma.currentPage.appendChild(frame);
                frame.x = currentX;
                frame.y = currentY;
                currentX += frame.width + 150;
            }
            if (createdFrames.length > 0) {
                figma.currentPage.selection = createdFrames;
                figma.viewport.scrollAndZoomIntoView(createdFrames);
            }
            figma.notify(notificationText || `¡Formatos KWCC importados al lienzo!`);
        }
    }
    catch (err) {
        const error = err;
        console.error("Figma Sandbox import error:", error);
        figma.notify(`Error al importar partido: ${error.message || String(error)}`);
    }
};
